[CmdletBinding()] param()
$ErrorActionPreference='Stop';Set-StrictMode -Version 2.0
function Assert-T($condition,$message){if(-not $condition){throw $message}}
function Import-F($ast,$name){$matches=@($ast.FindAll({param($node)$node-is[Management.Automation.Language.FunctionDefinitionAst]-and$node.Name-ceq$name},$true));if($matches.Count-ne1){throw "missing $name"};$body=$matches[0].Body.Extent.Text;Set-Item "Function:\script:$name" ([scriptblock]::Create($body.Substring(1,$body.Length-2)))}
$sourcePath=Join-Path $PSScriptRoot 'run_product_mapper_cycle.ps1';$tokens=$null;$errors=$null
