$holdText=(@($ast.FindAll({param($node)$node-is[Management.Automation.Language.FunctionDefinitionAst]-and$node.Name-ceq'Invoke-R93FormalSoakHold'},$true))[0].Extent.Text)
Assert-T ($holdText.IndexOf("schema = 'ese.v92.o01-product-started/v1'")-lt$holdText.IndexOf('[Diagnostics.Stopwatch]::StartNew()')) 'formal clock starts before STARTED barrier'

$clockState=[pscustomobject]@{milliseconds=[int64]0}
$clock={return [int64]$clockState.milliseconds}.GetNewClosure()
$records=[Collections.Generic.List[object]]::new()
$emit={param($record)$records.Add($record)|Out-Null}.GetNewClosure()
$adapterState=[pscustomobject]@{identity_checks=0;preexisting_checks=0;samples=0;refreshes=0}
$adapters=[pscustomobject]@{
    Exists={param($token)$adapterState.identity_checks++;return $token-eq77}.GetNewClosure()
    IsAccredited={param($token)$adapterState.identity_checks++;return $token-eq77}.GetNewClosure()
    VerifyPreexisting={$adapterState.preexisting_checks++;return $true}.GetNewClosure()
    Pause={$clockState.milliseconds+=60000}.GetNewClosure()
    Sample={$adapterState.samples++;return [pscustomobject]@{tcp_gate_state='CANDIDATE';udp_gate_state='CANDIDATE';same_generation=$true;generation=[uint64]9;tcp_reason_code=[uint16]0;udp_reason_code=[uint16]0}}.GetNewClosure()
}
$process=[pscustomobject]@{WorkingSet64=[int64]1048576;HandleCount=12;state=$adapterState}
$process|Add-Member -MemberType ScriptMethod -Name Refresh -Value {$this.state.refreshes++}
$state=[pscustomobject]@{elapsed_ms=[int64]0;sequence=0}
$null=Invoke-R93FormalSoakHold -Adapters $adapters -Token 77 -Process $process `
    -State $state -ClockMilliseconds $clock -EmitRecord $emit `
    -Mode NON_RELEASE_ACCELERATED
Assert-T ($records.Count-eq4-and$state.sequence-eq4-and$state.elapsed_ms-eq180000) 'accelerated hold did not emit exact records'
Assert-T ($adapterState.samples-eq3-and$adapterState.identity_checks-eq20-and$adapterState.preexisting_checks-eq7-and$adapterState.refreshes-eq3) 'hold did not preserve identity and refresh resources around every sample'
Assert-T ([string]$records[0].schema-ceq'ese.v92.o01-product-started/v1'-and$records[0].identity_accredited) 'started barrier invalid'
foreach($record in @($records|Select-Object -Skip 1)){
    Assert-T ([string]$record.schema-ceq'ese.v92.o01-product-sample/v1'-and$record.available-and$record.same_generation) 'sample projection invalid'
    Assert-T (($record|ConvertTo-Json -Compress)-notmatch'(?i)path|address|port|nonce|pid|credential') 'sample leaked private identity'
}

$badClockState=[pscustomobject]@{milliseconds=[int64]0}
$badAdapters=[pscustomobject]@{
    Exists={return $true};IsAccredited={return $true};Pause={$badClockState.milliseconds+=71000}.GetNewClosure()
    Sample={return $null}
}
$badState=[pscustomobject]@{elapsed_ms=[int64]0;sequence=0};$gapRejected=$false
try{$null=Invoke-R93FormalSoakHold -Adapters $badAdapters -Token 1 -Process $process -State $badState -ClockMilliseconds {return [int64]$badClockState.milliseconds}.GetNewClosure() -EmitRecord $emit -Mode NON_RELEASE_ACCELERATED}catch{$gapRejected=$_.Exception.Message-match'cadence'}
Assert-T $gapRejected 'sample gap was accepted'
$deathClock=[pscustomobject]@{milliseconds=[int64]0;alive=$true;samples=0}
$deathAdapters=[pscustomobject]@{
    Exists={param($token)return [bool]$deathClock.alive}.GetNewClosure()
    IsAccredited={param($token)return [bool]$deathClock.alive}.GetNewClosure()
    Pause={$deathClock.milliseconds=60000;$deathClock.alive=$false}.GetNewClosure()
    Sample={$deathClock.samples++;return $null}.GetNewClosure()
}
$deathRejected=$false
try{$null=Invoke-R93FormalSoakHold -Adapters $deathAdapters -Token 1 -Process $process -State ([pscustomobject]@{elapsed_ms=[int64]0;sequence=0}) -ClockMilliseconds {return [int64]$deathClock.milliseconds}.GetNewClosure() -EmitRecord $emit -Mode NON_RELEASE_ACCELERATED}catch{$deathRejected=$_.Exception.Message-match'identity changed before sample'}
Assert-T ($deathRejected-and$deathClock.samples-eq0) 'identity death during pause reached sampling'
$refreshProcess=[pscustomobject]@{WorkingSet64=[int64]1;HandleCount=1}
$refreshProcess|Add-Member -MemberType ScriptMethod -Name Refresh -Value {throw 'refresh injected failure'}
$refreshRejected=$false
try{$null=Invoke-R93FormalSoakHold -Adapters $adapters -Token 77 -Process $refreshProcess -State ([pscustomobject]@{elapsed_ms=[int64]0;sequence=0}) -ClockMilliseconds $clock -EmitRecord $emit -Mode NON_RELEASE_ACCELERATED}catch{$refreshRejected=$_.Exception.Message-match'resource refresh failed'}
Assert-T $refreshRejected 'resource refresh failure was accepted'
$formalClockRejected=$false
try{$null=Invoke-R93FormalSoakHold -Adapters $adapters -Token 77 -Process $process -State $state -ClockMilliseconds $clock -EmitRecord $emit -Mode FORMAL_RELEASE}catch{$formalClockRejected=$_.Exception.Message-match'injected clock'}
Assert-T $formalClockRejected 'formal mode accepted an injected clock';function Set-FPScopeIni{$scopeState.configure_calls++};function Invoke-FPScopeApi{[pscustomobject]@{tcp_candidate=$true;udp_candidate=$true;same_generation=$true;generation=[uint64]1;tcp_gate_state='CANDIDATE';udp_gate_state='CANDIDATE';tcp_reason_code=[uint16]0;udp_reason_code=[uint16]0}};function Invoke-FPScopeHold{param($token)$scopeState.hold_calls++};$scopeState=[pscustomobject]@{alive=$true;configure_calls=0;hold_calls=0};$scopeAdapters=[pscustomobject]@{Configure={Set-FPScopeIni;Set-FPScopeIni;Set-FPScopeIni};Start={77};AccreditNewProcess={param($token)$true};Exists={param($token)[bool]$scopeState.alive};IsAccredited={param($token)$true};VerifyPreexisting={};Sample={Invoke-FPScopeApi};Pause={};Close={param($token)$scopeState.alive=$false};WaitForExit={param($token)$true};MappingsAbsent={$true};RestoreIni={$true}};$scopeAfterObserved={param($token)Invoke-FPScopeHold $token};$scopeResult=Invoke-R93PartialCycle -Adapters $scopeAdapters -MaxSamples 1 -AfterObserved $scopeAfterObserved;$scopeAssignments=@($ast.FindAll({param($node)$node-is[Management.Automation.Language.AssignmentStatementAst]-and$node.Left.Extent.Text-cin@('$adapters.Configure','$adapters.Sample','$formalSoak')},$true));$rawScopeAssignments=@($scopeAssignments|Where-Object{$_.Right-is[Management.Automation.Language.CommandExpressionAst]-and$_.Right.Expression-is[Management.Automation.Language.ScriptBlockExpressionAst]});Assert-T ($scopeResult.status-ceq'MAPPING_OBSERVED_CLEAN_EXIT'-and$scopeResult.sample_observation.samples_total-eq1-and$scopeState.configure_calls-eq3-and$scopeState.hold_calls-eq1-and$scopeAssignments.Count-eq4-and$rawScopeAssignments.Count-eq3) 'formal configure/sample/soak callback lost script scope or regained a dynamic-module closure'
$availableState=[pscustomobject]@{alive=$true};$availableAdapters=[pscustomobject]@{Configure={};Start={1};AccreditNewProcess={};Exists={param($token)[bool]$availableState.alive}.GetNewClosure();IsAccredited={$true};VerifyPreexisting={};Sample={[pscustomobject]@{tcp_candidate=$false;udp_candidate=$false;same_generation=$false;generation=[uint64]1;tcp_gate_state='BLOCKED';udp_gate_state='BLOCKED';tcp_reason_code=[uint16]10;udp_reason_code=[uint16]10}};Pause={};Close={$availableState.alive=$false}.GetNewClosure();WaitForExit={$true};MappingsAbsent={$true};RestoreIni={$true}};$availableResult=Invoke-R93PartialCycle -Adapters $availableAdapters -MaxSamples 1;$availableFailureState=[pscustomobject]@{sequence=0};$availableWriter=[IO.StringWriter]::new();try{$availableRecord=Write-R93FormalFailureRecord -Result $availableResult -State $availableFailureState -Writer $availableWriter;$availableText=$availableWriter.ToString();Assert-T ($availableResult.failure_class-ceq'CANDIDATE_PAIR_NOT_OBSERVED'-and$availableResult.sample_observation.samples_total-eq1-and$availableResult.sample_observation.samples_available-eq1-and$availableResult.sample_observation.last_tcp_reason_code.GetType().FullName-ceq'System.Int32'-and$availableResult.sample_observation.last_udp_reason_code.GetType().FullName-ceq'System.Int32'-and$availableRecord.sequence-eq1-and$availableRecord.failure_class-ceq'CANDIDATE_PAIR_NOT_OBSERVED'-and$availableRecord.sample_observation.last_tcp_reason_code-eq10-and$availableText-ceq(($availableRecord|ConvertTo-Json -Compress -Depth 3)+[Environment]::NewLine)) 'available failure observation did not remain canonical Int32 or emit exactly one line'}finally{$availableWriter.Dispose()};$sourceText=[IO.File]::ReadAllText($sourcePath);function New-FPPlane($transport,$local,$grant,$generation){[pscustomobject]@{gate_state='CANDIDATE';reason_code=[uint16]0;generation=[uint64]$generation;local=[pscustomobject]@{port=$local};mapped=[pscustomobject]@{port=$grant};advertised=[pscustomobject]@{port=$grant};lease=[pscustomobject]@{generation=[uint64]$generation;transport=$transport;requested_external_port=$local;granted_external_port=$grant;owned_by_us=$true;structurally_valid=$true}}};function New-FPPayload{$tcp=New-FPPlane Tcp 41001 42001 12;$udp=New-FPPlane Udp 41002 42002 12;[pscustomobject]@{available=$true;data=[pscustomobject]@{schema='ESE_REACH_STATUS_V1';topology_generation=[uint64]12;planes=[pscustomobject]@{ed2k_tcp_v4=$tcp;kad_udp_v4=$udp}}}};function Assert-FPReject($mutator,$label){$payload=New-FPPayload;$null=&$mutator $payload;$projection=Get-R93FormalCandidateProjection $payload 41001 41002;Assert-T (-not[bool]$projection.same_generation) ("formal projector accepted "+$label)};$baseline=Get-R93FormalCandidateProjection (New-FPPayload) 41001 41002;Assert-T ($baseline.same_generation-and$baseline.tcp_candidate-and$baseline.udp_candidate) 'formal projector still requires primary evidence';$hostiles=@(@({param($p)$p.data.topology_generation=[uint64]0},'top generation'),@({param($p)$p.data.planes.ed2k_tcp_v4.generation=[uint64]13},'plane generation'),@({param($p)$p.data.planes.kad_udp_v4.lease.generation=[uint64]13},'lease generation'),@({param($p)$p.data.planes.ed2k_tcp_v4.lease.transport='Udp'},'transport'),@({param($p)$p.data.planes.kad_udp_v4.local.port=49999},'local port'),@({param($p)$p.data.planes.ed2k_tcp_v4.lease.requested_external_port=49999},'requested port'),@({param($p)$p.data.planes.kad_udp_v4.lease.granted_external_port=0},'granted port'),@({param($p)$p.data.planes.ed2k_tcp_v4.mapped.port=49999},'mapped port'),@({param($p)$p.data.planes.kad_udp_v4.advertised.port=49999},'advertised port'),@({param($p)$p.data.planes.ed2k_tcp_v4.lease.owned_by_us=$false},'ownership'),@({param($p)$p.data.planes.kad_udp_v4.lease.structurally_valid=$false},'structural validity'),@({param($p)$p.data.planes.ed2k_tcp_v4.gate_state='VERIFIED'},'candidate gate'));foreach($case in $hostiles){Assert-FPReject $case[0] $case[1]};$native=New-FPPayload;$native.data.planes.kad_udp_v4.gate_state='VERIFIED';$nativeProjection=Get-R93FormalCandidateProjection $native 41001 41002;Assert-T (-not$nativeProjection.same_generation-and$nativeProjection.udp_gate_state-ceq'VERIFIED') 'native gate state was accepted or corrupted';$enumSource=[IO.File]::ReadAllText((Join-Path $PSScriptRoot '..\..\..\srchybrid\UPnPImpl.h'));$wrapperSource=[IO.File]::ReadAllText((Join-Path $PSScriptRoot '..\..\..\srchybrid\UPnPImplWrapper.cpp'));$preferencesSource=[IO.File]::ReadAllText((Join-Path $PSScriptRoot '..\..\..\srchybrid\Preferences.cpp'));$iniSource=[IO.File]::ReadAllText((Join-Path $PSScriptRoot '..\..\..\srchybrid\Ini2.cpp'));$enumBody=[regex]::Match($enumSource,'enum\s+UPNP_IMPLEMENTATION\s*\{(?<body>[\s\S]*?)\};').Groups['body'].Value;$enumNames=@([regex]::Matches($enumBody,'UPNP_IMPL_[A-Z]+')|ForEach-Object{$_.Value});$enumCanonical=[regex]::Replace([regex]::Replace($enumBody,'(?s)/\*.*?\*/|//[^\r\n]*',''),'\s+','');Assert-T (($enumNames-join',')-ceq'UPNP_IMPL_WINDOWSERVICE,UPNP_IMPL_MINIUPNPLIB,UPNP_IMPL_NATPMP,UPNP_IMPL_PCP,UPNP_IMPL_NONE'-and$enumCanonical-ceq'UPNP_IMPL_WINDOWSERVICE=0,UPNP_IMPL_MINIUPNPLIB,UPNP_IMPL_NATPMP,UPNP_IMPL_PCP,UPNP_IMPL_NONE'-and@([regex]::Matches($wrapperSource,'new CUPnPImplPCP\(\)')).Count-eq1-and@([regex]::Matches($wrapperSource,'new CUPnPImplNATPMP\(\)')).Count-eq1-and$wrapperSource.IndexOf('new CUPnPImplPCP()')-lt$wrapperSource.IndexOf('new CUPnPImplNATPMP()')) 'mapper enum values or PCP to NAT-PMP order drifted';foreach($setting in @('LastWorkingImplementation 3','DisableMiniUPNPLibImpl 1','DisableWinServImpl 1')){Assert-T (@([regex]::Matches($sourceText,[regex]::Escape(('Set-LabIniValue $ini Connection '+$setting)))).Count-eq1) ('formal profile pin is not exact: '+$setting)};Assert-T ($preferencesSource.IndexOf('GetString(_T("IPv6BindAddr"), _T(""), _T("Connection"))')-ge0-and$preferencesSource.IndexOf('GetInt(_T("LastWorkingImplementation"), 1 /*MiniUPnPLib*/)')-gt$preferencesSource.IndexOf('GetString(_T("IPv6BindAddr"), _T(""), _T("Connection"))')-and$iniSource.Contains('m_strSection = lpszSection')) 'INI section cursor contract drifted';$failureObservation=[pscustomobject][ordered]@{samples_total=180;samples_available=180;tcp_candidate_samples=0;udp_candidate_samples=0;same_generation_samples=0;last_tcp_gate_state='BLOCKED';last_udp_gate_state='BLOCKED';last_tcp_reason_code=10;last_udp_reason_code=10};$emitterText=(@($ast.FindAll({param($node)$node-is[Management.Automation.Language.FunctionDefinitionAst]-and$node.Name-ceq'Write-R93FormalFailureRecord'},$true))[0].Extent.Text);Assert-T ($emitterText.IndexOf('.WriteLine(')-lt$emitterText.IndexOf('.Flush()')) 'failure writer did not flush after newline';Assert-T ($sourceText.Contains('Write-R93FormalFailureRecord -Result $result -State $formalState;exit 1')) 'failure record is not emitted before exit';$failureClasses=@('CANDIDATE_PAIR_NOT_OBSERVED','EXECUTION_FAILED','IDENTITY_NOT_ACCREDITED','INI_RESTORE_FAILED','PREEXISTING_PROCESS_CHANGED','PROCESS_STILL_ALIVE');foreach($failureClass in $failureClasses){$failureState=[pscustomobject]@{sequence=0};$failureWriter=[IO.StringWriter]::new();try{$failureResult=[pscustomobject]@{failure_class=$failureClass;cleanup_failure_class=$null;sample_observation=$failureObservation};$failureRecord=Write-R93FormalFailureRecord -Result $failureResult -State $failureState -Writer $failureWriter;Assert-T ($failureState.sequence-eq1-and$failureRecord.sequence-eq1-and$failureRecord.failure_class-ceq$failureClass-and$failureRecord.sample_observation.last_tcp_reason_code-eq10) 'failure sequence/class invalid';Assert-T ($failureWriter.ToString().EndsWith([Environment]::NewLine)) 'failure record lacks terminal newline'}finally{$failureWriter.Dispose()}};$terminalState=[pscustomobject]@{sequence=481};$terminalWriter=[IO.StringWriter]::new();try{$terminalRecord=Write-R93FormalFailureRecord -Result ([pscustomobject]@{failure_class='MAPPING_REMAINS_UNTOUCHED';cleanup_failure_class='MAPPING_REMAINS_UNTOUCHED';sample_observation=$failureObservation}) -State $terminalState -Writer $terminalWriter;Assert-T ($terminalRecord.sequence-eq482-and$terminalRecord.failure_class-ceq'EXECUTION_FAILED'-and$terminalRecord.cleanup_failure_class-ceq'MAPPING_REMAINS_UNTOUCHED') 'cleanup-only failure normalization invalid'}finally{$terminalWriter.Dispose()};[pscustomobject]@{schema='ese.v92.o01-product-soak-mock/v1';verdict='PASS';formal_evidence_emitted=$false}|ConvertTo-Json -Compress
